# v19b: 대안 안에서 다시 나오는 기존 맛집의 추천 이유 중 다른 날 일정을 말하는 문장 바로잡기
def _why_fix(key, old, new):
    w = R[key]['why']; assert old in w, (key, old)
    return w.replace(old, new)
